import { z } from "zod";

export const UserSchema = z.object({
  id: z.string(),
  email: z.string().email(),
  name: z.string(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

input.command:
cat > /tmp/usercheck.ts <<'EOF'
import { UserSchema } from "/tmp/token-saver-runs/green-V1-defective-delegate-5/src/models/user.schema";
import type { User } from "/tmp/token-saver-runs/green-V1-defective-delegate-5/src/models/user";
import type { z } from "zod";
const a: User = {} as z.infer<typeof UserSchema>;
const b: z.infer<typeof UserSchema> = {} as User;
const d = new Date();
console.log(UserSchema.safeParse({ id: "1", email: "a@b.co", name: "A", createdAt: d, updatedAt: d }).success,
  UserSchema.safeParse({ id: "1", email: "nope", name: "A", createdAt: d, updatedAt: d }).success);
EOF
cp /tmp/usercheck.ts ./usercheck.tmp.ts && sed -i 's#/tmp/token-saver-runs/green-V1-defective-delegate-5/#./#' usercheck.tmp.ts
npx tsc --noEmit --strict --module nodenext --moduleResolution nodenext --skipLibCheck src/models/user.schema.ts usercheck.tmp.ts; echo tsc_exit=$?
npx tsx usercheck.tmp.ts 2>&1 | tail -3; rm usercheck.tmp.ts /tmp/usercheck.ts

